// =====================================================================
// APPLY
// =====================================================================
function applyTrack(file, mastery, key) {
  const p = path.join(ROOT, file);
  const d = JSON.parse(fs.readFileSync(p, "utf8"));
  const ai = AI_ASSIST[key];
  const sh = STAKEHOLDER[key] || {};
  let m = 0, a = 0, s = 0;
  for (const w of d.weeks) {
    if (mastery[w.number] && mastery[w.number].length === 10) {
      w.mastery_questions = mastery[w.number];
      m++;
    }
    if (ai) {
      w.ai_assist = ai.template(w);
      a++;
    }
    if (sh[w.number]) {
      w.stakeholder_moment = sh[w.number];
      s++;
    }
  }
  fs.writeFileSync(p, JSON.stringify(d, null, 2) + "\n");
  console.log(`${file}: mastery=${m}, ai=${a}, stakeholder=${s}`);
}

applyTrack("ml-engineering.json", ML, "ml-engineering");
applyTrack("full-stack-web.json", FS, "full-stack-web");
applyTrack("mobile-engineering.json", MO, "mobile-engineering");
applyTrack("devops-cloud.json", DC, "devops-cloud");
